sealed class OneWindowPolicy : IRunicHostedWindowPolicy
{
    public ValueTask<RunicHostedWindowDecision> OpenWindowAsync(RunicHostedWindowRequest request, CancellationToken cancellationToken) =>
        ValueTask.FromResult(request.Application.Windows.Count == 0
            ? RunicHostedWindowDecision.Allow(request.WindowOptions with { Placement = SavedPlacement(request) })
            : RunicHostedWindowDecision.Refuse("This host shows one window of each tool."));

    public RunicHostedPresentationDecision Present(RunicHostedPresentationRequest request) =>
        request.Kind == RunicHostedPresentationKind.SetFullScreen ? RunicHostedPresentationDecision.Refuse() : RunicHostedPresentationDecision.Allow();
}

// Let a trusted tool write the clipboard from any of its windows, and paste only as plain text.
public ValueTask<RunicHostedServiceDecision> ServiceAsync(RunicHostedServiceRequest request, CancellationToken cancellationToken) =>
    ValueTask.FromResult(request.Kind switch
    {
        RunicHostedServiceKind.ClipboardWrite => RunicHostedServiceDecision.Apply(request with { ClipboardFormats = DesktopClipboardFormats.Text }),
        _ => request.IsAllowedByDefault ? RunicHostedServiceDecision.Allow() : RunicHostedServiceDecision.Refuse(),
    });

